import{_ as a,o as t,c as n,a3 as s}from"./chunks/framework.DH50UWNB.js";const p=JSON.parse(`{"title":"License","description":"The licenses that cover Wake's server and web app, the free plan, the CLI and the integrations, the documentation and older releases.","frontmatter":{"description":"The licenses that cover Wake's server and web app, the free plan, the CLI and the integrations, the documentation and older releases."},"headers":[],"relativePath":"reference/license.md","filePath":"reference/license.md","lastUpdated":1794486787000}`),r={name:"reference/license.md"};function o(i,e,h,l,c,d){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h1><p>Two licenses cover Wake, a third its documentation, and a fourth its older releases.</p><h2 id="the-server-and-the-web-app" tabindex="-1">The server and the web app <a class="header-anchor" href="#the-server-and-the-web-app" aria-label="Permalink to &quot;The server and the web app&quot;">​</a></h2><p>The server and the web app, with the rest of what an installation runs, are under the <strong>Wake Free License</strong> (<code>LicenseRef-Wake-Free-License</code>) from v2.4.0. You may use, copy and run Wake, except:</p><ul><li>offering it to others as a hosted or managed service;</li><li>removing or obscuring its licensing notices;</li><li>getting around its license-key functionality or the free plan&#39;s limits, such as the number of people, or removing what enforces them.</li></ul><p>Letting the people the free plan allows use an installation you run is not offering it as a hosted or managed service.</p><p>The terms grant no right to use the Wake name or logo, except to say truthfully that your work uses or is based on Wake. The laws of Spain govern them, and the courts of the licensor&#39;s domicile in Spain decide a dispute, unless the law gives you other courts, such as those where you live as a consumer. You run Wake on your own machines and keep your data and its backups; the terms limit liability only as far as the law allows.</p><h2 id="the-free-plan" tabindex="-1">The free plan <a class="header-anchor" href="#the-free-plan" aria-label="Permalink to &quot;The free plan&quot;">​</a></h2><p>Under the free plan, at most 3 people in all may use Wake for you and your company, however many installations you run, each with their own account, unless a paid license allows more. An account is never shared between people. Everyone who uses Wake through a bot, an integration or a shared tool counts as a person; agents and API clients never count themselves. An installation is one running copy of the server with its database, on however many machines or containers.</p><p>Each installation holds its part of the limit itself, 3 accounts: see <a href="/wake-dist/docs/run/sign-up#free-plan-accounts">Free plan accounts</a>.</p><h2 id="the-cli-and-the-integrations" tabindex="-1">The CLI and the integrations <a class="header-anchor" href="#the-cli-and-the-integrations" aria-label="Permalink to &quot;The CLI and the integrations&quot;">​</a></h2><p>The <code>wake</code> CLI and the agent integrations that <code>wake connect</code> installs, with what they ship with, are under the <strong>MIT</strong> license: use them anywhere.</p><h2 id="the-documentation" tabindex="-1">The documentation <a class="header-anchor" href="#the-documentation" aria-label="Permalink to &quot;The documentation&quot;">​</a></h2><p>These docs are under <strong>CC BY 4.0</strong>, the Creative Commons Attribution 4.0 International license: copy, translate or quote them for any purpose, naming David Alonso as their author.</p><h2 id="older-releases" tabindex="-1">Older releases <a class="header-anchor" href="#older-releases" aria-label="Permalink to &quot;Older releases&quot;">​</a></h2><p>v2.3.0 and earlier stay under the license they were released with: FSL-1.1-ALv2, the Functional Source License, version 1.1, with the Apache 2.0 future license.</p><h2 id="read-the-terms" tabindex="-1">Read the terms <a class="header-anchor" href="#read-the-terms" aria-label="Permalink to &quot;Read the terms&quot;">​</a></h2><p>Each release carries its terms as <code>LICENSE</code>:</p><ul><li>The installer writes them into the installation&#39;s directory as <code>LICENSE</code>, and its checklist says <code>✓ License: Wake Free License</code>. Each upgrade replaces the file with the new release&#39;s.</li><li>Each release lists <code>LICENSE</code> among its files, covered by its signed checksums; see <a href="/wake-dist/docs/reference/verify-installer#what-the-checksums-cover">Verify a download</a>.</li><li>Each image carries it at <code>/usr/share/licenses/wake/LICENSE</code>; see <a href="/wake-dist/docs/run/images#the-images">The images</a>.</li><li>The web app names the license in <strong>About this Wake</strong>.</li></ul>',19)])])}const m=a(r,[["render",o]]);export{p as __pageData,m as default};
